SELECT city, CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(AVG(rating), 2) AS avg_rating, COUNT(*) AS num_suppliers FROM suppliers WHERE city IN ('New York', 'Bangkok') AND city = 'Chiang Mai' GROUP BY city, CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END ORDER BY avg_rating DESC, city, rating_bucket LIMIT 1
